/**
 * TinyMCE 6 Icon Picker Plugin
 *
 * @author Paris.fr Theme
 */
( function () {
    var themeiconpicker = (function () {
        'use strict';
        tinymce.PluginManager.requireLangPack( 'themeiconpicker', 'fr_FR');
        tinymce.PluginManager.add('themeiconpicker', function (editor, url) {

            // Register icon for the button
            editor.ui.registry.addIcon('themeiconpicker','<svg  xmlns="http://www.w3.org/2000/svg"  width="24"  height="24"  viewBox="0 0 24 24"  fill="none"  stroke="currentColor"  stroke-width="2"  stroke-linecap="round"  stroke-linejoin="round"  class="icon icon-tabler icons-tabler-outline icon-tabler-icons"><path stroke="none" d="M0 0h24v24H0z" fill="none"/><path d="M6.5 6.5m-3.5 0a3.5 3.5 0 1 0 7 0a3.5 3.5 0 1 0 -7 0" /><path d="M2.5 21h8l-4 -7z" /><path d="M14 3l7 7" /><path d="M14 10l7 -7" /><path d="M14 14h7v7h-7z" /></svg>' );

            let iconsData = [];

            // Fallback: Load icons from HTML file
            const loadIconsData = async () => {
                try {
                    const response = await fetch(url + '/html/icons.html');
                    const html = await response.text();
                    const parser = new DOMParser();
                    const doc = parser.parseFromString(html, 'text/html');
                    const articles = doc.querySelectorAll('article[title]');
                    
                    iconsData = Array.from(articles).map(article => {
                        const title = article.getAttribute('title');
                        const svg = article.querySelector('svg');
                        return {
                            name: title,
                            svg: svg ? svg.outerHTML : ''
                        };
                    }).filter(icon => icon.svg);
                } catch (error) {
                    console.error('Error loading icons from HTML:', error);
                    iconsData = [];
                }
            };

            // Create icon HTML for display
            const createIconHTML = (icon) => {
                return `
                    <div class="icon-item" data-name="${icon.name}" style="
                        display: flex;
                        flex-direction: column;
                        align-items: center;
                        padding: 8px;
                        cursor: pointer;
                        border: 1px solid transparent;
                        border-radius: 4px;
                        transition: all 0.2s;
                    " onmouseover="this.style.backgroundColor='#f0f0f0'; this.style.borderColor='#ccc';" 
                    onmouseout="this.style.backgroundColor=''; this.style.borderColor='transparent';">
                        <div style="width: 100px; height: 100px; margin-bottom: 4px;">
                            ${icon.svg}
                        </div>
                        <span style="font-size: 10px; text-align: center; word-break: break-word; max-width: 60px;">${icon.name}</span>
                    </div>
                `;
            };

            // Filter icons based on search term
            const filterIcons = (searchTerm) => {
                if (!searchTerm) return iconsData;
                return iconsData.filter(icon => 
                    icon.name.toLowerCase().includes(searchTerm.toLowerCase())
                );
            };

            // Render icons grid
            const renderIconsGrid = (icons ) => {
                const grid = document.createElement('div');
                grid.style.cssText = `
                    display: grid;
                    grid-template-columns: repeat(4, 1fr);
                    gap: 8px;
                    max-height: 400px;
                    overflow-y: auto;
                    padding: 8px;
                `;

                icons.forEach(icon => {
                    const iconElement = document.createElement('div');
                    iconElement.innerHTML = createIconHTML(icon);
                    grid.appendChild(iconElement.firstElementChild);
                });

                return grid;
            };

            // Insert selected icon into editor
            const insertIcon = (icon, customSize = null) => {
                let iconSvg = icon.children[0].innerHTML;
                
                // Get selected size from radio buttons or use custom size
                let selectedSize = customSize;
                if (!selectedSize) {
                    const sizeRadio = document.querySelector('input[name="iconSize"]:checked');
                    selectedSize = sizeRadio ? sizeRadio.value : '24';
                }
                
                // Replace width and height attributes
                iconSvg = iconSvg
                    .replace(/width="100"/, `width="${selectedSize}"`)
                    .replace(/height="100"/, `height="${selectedSize}"`);

                editor.insertContent(iconSvg);
                editor.windowManager.close();
            };

            // Open icon picker dialog
            const openIconPicker = () => {
                
                const icons=renderIconsGrid( iconsData ).outerHTML;
                const sizeRadioHTML = `
                    <div style="display:flex; align-items:center; margin: 10px 0; padding: 10px; border: 1px solid #ddd; border-radius: 4px; background-color: #f9f9f9;">
                        <label style="font-weight: bold; margin-inline-end: 8px; display: block;">Icon Size:</label>
                        <div style="display: flex; gap: 15px; flex-wrap: wrap;">
                            <label style="display: flex; align-items: center; cursor: pointer;">
                                <input type="radio" name="iconSize" value="16" style="margin-right: 5px;">
                                16px
                            </label>
                            <label style="display: flex; align-items: center; cursor: pointer;">
                                <input type="radio" name="iconSize" value="24" checked style="margin-right: 5px;">
                                24px (default)
                            </label>
                            <label style="display: flex; align-items: center; cursor: pointer;">
                                <input type="radio" name="iconSize" value="48" style="margin-right: 5px;">
                                48px
                            </label>
                            <label style="display: flex; align-items: center; cursor: pointer;">
                                <input type="radio" name="iconSize" value="64" style="margin-right: 5px;">
                                64px
                            </label>
                            <label style="display: flex; align-items: center; cursor: pointer;">
                                <input type="radio" name="iconSize" value="100" style="margin-right: 5px;">
                                100px
                            </label>
                        </div>
                    </div>
                `;
                const htmlPanelContent=`${sizeRadioHTML}<div id="icons-container" style="border: 1px solid #ccc; border-radius: 4px; min-height: 300px;">${icons}</div>`

                const dialogConfig = {
                    title: 'Select Icon',
                    size: 'large',
                    body: {
                        type: 'panel',
                        items: [
                            {
                                type: 'input',
                                name: 'search',
                                label: 'Search icons:',
                                placeholder: 'Type to search...'
                            },
                            {
                                type: 'htmlpanel',
                                html: htmlPanelContent
                            }
                        ]
                    },
                    buttons: [
                        {
                            type: 'cancel',
                            text: 'Cancel'
                        }
                    ],
                    onChange: (api, details) => {
                        if (details.name === 'search') {
                            const searchTerm = api.getData().search;
                            const container = document.querySelector('#icons-container');
                            const filteredIcons = filterIcons(searchTerm);
                            container.innerHTML = renderIconsGrid(filteredIcons).outerHTML;
                            const icons = container.querySelectorAll('.icon-item');
                            icons.forEach(icon => {
                                icon.addEventListener('click', () => {
                                    insertIcon(icon);
                                });
                            });
                        }
                    },
                 
                };

                const dialog = editor.windowManager.open(dialogConfig);

                const container = document.querySelector('#icons-container');
                const dialogIcons = container.querySelectorAll('.icon-item');
                dialogIcons.forEach(icon => {
                    icon.addEventListener('click', () => {
                        insertIcon(icon);
                    });
                });
               
            };

            // Load icons when plugin initializes
            loadIconsData();

            // Register the icon picker button
            editor.ui.registry.addButton('themeiconpicker', {
                icon: 'themeiconpicker',
                tooltip: 'Insert Icon',
                onAction: () => {
                    openIconPicker();
                }
            });

        });
    }());
})();